    ["Holocall with {name}. Tap the phone button to hang up."] = "Holollamada con {name}. Toca el botón del teléfono para colgar.",
    ["Live holocall picture (experimental)"] = "Imagen en vivo de la holollamada (experimental)",
    ["YouTube on V’s TV"] = "YouTube en la TV de V",
    ["In V’s apartments the TV offers YouTube: pick a video and watch it with your companion, who can talk about it.\n\nThe video plays in a window over the game, so use Windowed Borderless or Windowed mode."] = "En los apartamentos de V, la TV ofrece YouTube: elige un vídeo y míralo con tu compañero, que puede hablar de él.\n\nEl vídeo se reproduce en una ventana sobre el juego, así que usa el modo Ventana sin bordes o Ventana.",
    ["YouTube"] = "YouTube",
    ["YouTube: pause or play"] = "YouTube: pausar o reproducir",
    ["YouTube: stop"] = "YouTube: detener",
    ["YouTube could not open on the TV. Try again."] = "YouTube no se pudo abrir en la TV. Inténtalo de nuevo.",
    ["YouTube could not open on the TV. Use Windowed Borderless or Windowed mode and try again."] = "YouTube no se pudo abrir en la TV. Usa el modo Ventana sin bordes o Ventana e inténtalo de nuevo.",
    ["YouTube on the TV is turned off in the settings."] = "YouTube en la TV está desactivado en los ajustes.",
